{
  "PROP-6a4369e9-inv-036": {
    "property_id": "PROP-6a4369e9-inv-036",
    "audit_result": {
      "property_id": "PROP-6a4369e9-inv-036",
      "classification": "potential-vulnerability",
      "code_path": "beacon-chain/sync/subscriber_beacon_blocks.go::processDataColumnSidecarsFromExecution::L154",
      "proof_trace": "Property claims broadcasts only occur on subscribed subnets. The code iterates over custody columns and broadcasts each, but line 154 passes sidecar.Index (column index) directly as the subnet parameter instead of computing the subnet via peerdas.ComputeSubnetForDataColumnSidecar(). This works on mainnet where subnets==columns (both 128), but violates the property on configurations where they differ.",
      "attack_scenario": "On a network with fewer subnets than columns (e.g., 64 subnets for 128 columns), a node would attempt to broadcast data columns on subnet IDs that equal high column indices (64-127), which are not valid subnet IDs and not subscribed, causing broadcast failures or publishing to unintended topics.",
      "checklist_id": "PROP-6a4369e9-inv-036"
    },
    "text": "Publishing data columns must only occur on subnets the node is subscribed to (custody/sampling).",
    "assertion": "forall col: published(col, subnet) => subscribed(subnet, custody) || subscribed(subnet, sampling)",
    "covers": "SG-010",
    "severity": "MEDIUM",
    "type": "invariant"
  }
}

